"""Source-gated Native construction calls for the nine one-way side controls."""

from __future__ import annotations

import hashlib
import json
from pathlib import Path

from one_way_side_observations import polyline

ASSIGNMENT = "testing__C412262__NRS-484B-493__motor_vehicle_driver"


def _hash(value, name):
    if not isinstance(value, str) or len(value) != 64 or any(c not in "0123456789abcdef" for c in value):
        raise ValueError("original reviewed source hash required: " + name)


def load_case(case_id: str) -> dict:
    plan = json.loads((Path(__file__).resolve().parent / "case-plan.json").read_text())
    case = next((entry for entry in plan["cases"] if entry["case_id"] == case_id), None)
    if case is None or not case_id.startswith(ASSIGNMENT + "__"):
        raise ValueError("unknown exact one-way parking case")
    return case


def validate_site(path: str | Path, case_id: str) -> dict:
    case = load_case(case_id)
    raw = Path(path).read_bytes()
    site = json.loads(raw)
    if (site.get("assignment_id") != ASSIGNMENT or site.get("cell_id") != "C412262" or
            site.get("source_kind") != "original_reviewed_street_survey" or
            site.get("review_status") != "reviewed"):
        raise ValueError("original reviewed street site and assignment required")
    for name in ("map_sha256", "street_status_sha256", "one_way_order_sha256", "street_boundary_sha256",
                 "permitted_direction_sha256", "device_erection_sha256",
                 "device_authority_sha256", "device_content_sha256", "device_extent_sha256"):
        _hash(site.get(name), name)
        records = site.get("source_records")
        record = records.get(name) if isinstance(records, dict) else None
        if not isinstance(record, dict) or not isinstance(record.get("path"), str):
            raise ValueError("reviewed original source record required: " + name)
        relative = Path(record["path"])
        if relative.is_absolute() or ".." in relative.parts or not relative.parts:
            raise ValueError("reviewed original source path escapes site: " + name)
        site_dir = Path(path).resolve().parent
        unresolved = site_dir / relative
        target = unresolved.resolve()
        if (site_dir not in target.parents or unresolved.is_symlink() or
                not target.is_file() or
                hashlib.sha256(target.read_bytes()).hexdigest() != site[name] or
                record.get("sha256") != site[name]):
            raise ValueError("reviewed original source bytes changed: " + name)
    if site.get("street_direction_variant") != case["street_direction_request"]:
        raise ValueError("reviewed street-direction variant differs from case")
    if site.get("notice_variant") != case["notice_request"]:
        raise ValueError("reviewed notice variant differs from case")
    polyline(site.get("lane_route_xy_m"))
    if not isinstance(site.get("notice_device"), dict):
        raise ValueError("reviewed official notice-device survey required")
    if site["notice_variant"] != "absent":
        device = site["notice_device"]
        for name in ("blueprint_id", "exact_notice_text", "erecting_authority_id",
                     "governing_extent_id"):
            if not isinstance(device.get(name), str) or not device[name]:
                raise ValueError("reviewed notice-device field required: " + name)
    site["_source_sha256"] = hashlib.sha256(raw).hexdigest()
    return site


def construct(adapter, site_path: str | Path, case_id: str) -> dict:
    case = load_case(case_id)
    site = validate_site(site_path, case_id)
    owned = []
    try:
        adapter.configure_street(site["street_direction_variant"], site["lane_route_xy_m"])
        if adapter.read_street_direction() != site["street_direction_variant"]:
            raise ValueError("Native street direction differs from reviewed site")
        if site["notice_variant"] != "absent":
            device = adapter.spawn_notice_device(site["notice_device"])
            if not device:
                raise ValueError("official notice-device spawn failed")
            owned.append(device)
        observed_notice = adapter.read_notice()
        if not isinstance(observed_notice, dict) or observed_notice.get("state") != site["notice_variant"]:
            raise ValueError("Native notice erection or extent readback differs")
        if site["notice_variant"] != "absent":
            for key in ("exact_notice_text", "erecting_authority_id", "governing_extent_id"):
                if observed_notice.get(key) != site["notice_device"][key]:
                    raise ValueError("Native notice content or authority readback differs: " + key)
        vehicle = adapter.spawn_vehicle(site["lane_route_xy_m"][0])
        if not vehicle:
            raise ValueError("subject vehicle spawn failed")
        owned.append(vehicle)
        adapter.drive_to_side(vehicle, case["vehicle_side_request"], site["lane_route_xy_m"])
        adapter.hold_for_activity(vehicle, case["activity_request"])
        observed = adapter.read_vehicle_state(vehicle)
        if not isinstance(observed, dict) or observed.get("activity_request") != case["activity_request"]:
            raise ValueError("Native vehicle activity readback differs")
        return {"case_id": case_id, "site_source_sha256": site["_source_sha256"],
                "owned": tuple(owned), "activity_request": case["activity_request"],
                "side_request": case["vehicle_side_request"],
                "physical_limit": "Original body geometry and activity purpose require post-capture review."}
    except Exception:
        for actor in reversed(owned):
            adapter.destroy(actor)
        raise

"""Source-bound lane-relative vehicle geometry for NRS 484B.493."""

import argparse
import hashlib
import json
import math
from pathlib import Path

ASSIGNMENT_ID = "testing__C412262__NRS-484B-493__motor_vehicle_driver"


def digest(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def point(raw):
    if not isinstance(raw, list) or len(raw) != 2 or any(isinstance(x, bool) or not isinstance(x, (float, int)) or not math.isfinite(x) for x in raw):
        raise ValueError("finite original XY point required")
    return tuple(float(x) for x in raw)


def polyline(raw):
    if not isinstance(raw, list) or len(raw) < 2:
        raise ValueError("original direction centerline required")
    points = [point(x) for x in raw]
    if any(a == b for a, b in zip(points, points[1:])):
        raise ValueError("nonzero centerline segments required")
    return points


def signed_offset(p, route):
    candidates = []
    for i, (a, b) in enumerate(zip(route, route[1:])):
        dx, dy = b[0] - a[0], b[1] - a[1]
        length2 = dx * dx + dy * dy
        t = max(0, min(1, ((p[0] - a[0]) * dx + (p[1] - a[1]) * dy) / length2))
        projection = (a[0] + t * dx, a[1] + t * dy)
        distance = math.dist(p, projection)
        cross = dx * (p[1] - a[1]) - dy * (p[0] - a[0])
        candidates.append((distance, i, cross / math.sqrt(length2)))
    _, segment, offset = min(candidates)
    return {"route_segment_index": segment, "signed_left_offset_m": offset}


def observe(case_id, context_path, trace_path, receipt_path):
    if not case_id.startswith(ASSIGNMENT_ID + "__"):
        raise ValueError("exact case identity required")
    receipt = json.loads(Path(receipt_path).read_text(encoding="utf-8"))
    if receipt.get("source_kind") != "original_native_capture" or receipt.get("diagnostic_fixture"):
        raise ValueError("original Native capture required")
    if (receipt.get("assignment_id"), receipt.get("case_id")) != (ASSIGNMENT_ID, case_id):
        raise ValueError("source receipt identity mismatch")
    if receipt.get("context_sha256") != digest(context_path) or receipt.get("trace_sha256") != digest(trace_path):
        raise ValueError("original source bytes changed")
    context = json.loads(Path(context_path).read_text(encoding="utf-8"))
    if context.get("case_id") != case_id:
        raise ValueError("context case identity mismatch")
    for key in ("street_legal_status_source", "street_boundary_source", "public_access_source",
                "city_limits_source", "one_way_order_source", "permitted_direction_source",
                "centerline_source", "notice_erection_source", "notice_authority_source",
                "notice_exact_content_source", "notice_conformity_source", "notice_extent_source",
                "person_identity_source", "vehicle_identity_source", "halt_purpose_source",
                "service_activity_source", "occupancy_source"):
        if not context.get(key):
            raise ValueError("original context source missing: " + key)
    if context.get("one_way_status") not in {"one_way", "two_way", "unresolved"}:
        raise ValueError("source-backed one-way status required")
    if context.get("notice_state") not in {"erected_applicable", "absent", "outside_extent", "unresolved"}:
        raise ValueError("source-backed notice state required")
    route = polyline(context.get("permitted_direction_centerline_xy_m"))
    rows = [json.loads(line) for line in Path(trace_path).read_text(encoding="utf-8").splitlines() if line]
    if len(rows) < 2 or receipt.get("fps") != 20 or receipt.get("frame_count") != len(rows):
        raise ValueError("original 20 Hz frame count required")
    samples = []
    for i, row in enumerate(rows):
        if row.get("frame") != i or isinstance(row.get("time_s"), bool) or not isinstance(row.get("time_s"), (int, float)) or not math.isfinite(row["time_s"]) or abs(row["time_s"] - i / 20) > .002:
            raise ValueError("original frame cadence mismatch")
        center = point(row.get("vehicle_center_xy_m"))
        body_raw = row.get("vehicle_body_polygon_xy_m")
        if not isinstance(body_raw, list) or len(body_raw) < 3:
            raise ValueError("original vehicle body polygon required")
        body = [point(x) for x in body_raw]
        speed = row.get("vehicle_speed_mps")
        if isinstance(speed, bool) or not isinstance(speed, (int, float)) or not math.isfinite(speed) or speed < 0:
            raise ValueError("original nonnegative speed required")
        center_offset = signed_offset(center, route)
        body_offsets = [signed_offset(x, route)["signed_left_offset_m"] for x in body]
        samples.append({"frame": i, "time_s": row["time_s"], "vehicle_speed_mps": speed,
                        "vehicle_center_signed_left_offset_m": center_offset["signed_left_offset_m"],
                        "nearest_route_segment_index": center_offset["route_segment_index"],
                        "body_signed_left_offset_range_m": [min(body_offsets), max(body_offsets)]})
    return {"assignment_id": ASSIGNMENT_ID, "case_id": case_id,
            "source_bindings": {"context_sha256": digest(context_path), "trace_sha256": digest(trace_path),
                                "receipt_sha256": digest(receipt_path)},
            "one_way_status_source_label": context["one_way_status"],
            "notice_state_source_label": context["notice_state"], "samples": samples,
            "left_hand_side_judgment": "unresolved", "stand_or_park_judgment": "unresolved",
            "notice_legal_applicability_judgment": "unresolved", "physical_acceptance": "unverified"}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    for name in ("case", "context", "trace", "receipt", "output"):
        parser.add_argument("--" + name, required=True)
    args = parser.parse_args()
    result = observe(args.case, args.context, args.trace, args.receipt)
    Path(args.output).write_text(json.dumps(result, indent=2, sort_keys=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()

"""Independent original-source audit for nine cases and eight comparisons."""

from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path

from comparison_audit import audit as compare
from saved_finalizer import finalize
from street_scene_construction import ASSIGNMENT


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def audit(index_path: Path) -> dict:
    index_path = Path(index_path)
    index = json.loads(index_path.read_text())
    plan = json.loads((Path(__file__).resolve().parent / "case-plan.json").read_text())
    if index.get("assignment_id") != ASSIGNMENT or index.get("source_kind") != "original_native_delivery":
        raise ValueError("original delivery index identity/source mismatch")
    cases = index.get("cases")
    expected = {case["case_id"] for case in plan["cases"]}
    if not isinstance(cases, dict) or set(cases) != expected:
        raise ValueError("exact nine original delivery cases required")
    packets = {}
    for case_id, names in cases.items():
        if not isinstance(names, dict) or set(names) != {"context", "trace", "receipt", "camera_manifest", "measurement"}:
            raise ValueError("original delivery source inventory incomplete: " + case_id)
        paths = {}
        for key, item in names.items():
            if not isinstance(item, dict) or not item.get("path") or not item.get("sha256"):
                raise ValueError("original delivery source binding missing: " + case_id)
            relative = Path(item["path"])
            if relative.is_absolute() or ".." in relative.parts:
                raise ValueError("original delivery source path escapes index")
            origin = index_path.parent.resolve()
            unresolved = origin / relative
            path = unresolved.resolve()
            if (origin not in path.parents or unresolved.is_symlink() or
                    not path.is_file() or sha(path) != item["sha256"]):
                raise ValueError("original delivery source changed: " + case_id + ": " + key)
            paths[key] = path
        measured = finalize(case_id, paths["context"], paths["trace"], paths["receipt"],
                            paths["camera_manifest"])
        saved = json.loads(paths["measurement"].read_text())
        if saved != measured or saved.get("physical_acceptance") != "unverified":
            raise ValueError("saved original measurement differs or overclaims: " + case_id)
        packets[case_id] = paths
    comparisons = {}
    for row in plan["comparisons"]:
        left, right = row["case_ids"]
        packet = lambda key: {"case_id": key, "context": str(packets[key]["context"]),
                              "trace": str(packets[key]["trace"]),
                              "receipt": str(packets[key]["receipt"])}
        comparisons[row["comparison_id"]] = compare(row["comparison_id"], packet(left), packet(right))
    return {"assignment_id": ASSIGNMENT, "source_kind": "original_native_delivery",
            "case_count": len(packets), "comparison_count": len(comparisons),
            "index_sha256": sha(index_path), "legal_judgment": "unresolved",
            "physical_acceptance": "unverified",
            "comparisons": comparisons}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--index", required=True, type=Path)
    parser.add_argument("--output", required=True, type=Path)
    args = parser.parse_args()
    args.output.write_text(json.dumps(audit(args.index), sort_keys=True, indent=2) + "\n")


if __name__ == "__main__":
    main()
